  CONSTRAINT `ai_generations_ibfk_2` FOREIGN KEY (`job_id`) REFERENCES `ai_jobs` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=183 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
