INSERT INTO `ai_jobs` VALUES (16,50,'course_draft','done',6,6,'','','{\"outline\": {\"tags\": [\"scikit-learn\", \"機械学習\", \"Python\", \"pandas\", \"分類\", \"データ前処理\", \"モデル評価\"], \"title\": \"scikit-learn入門：前処理から評価までの機械学習ワークフロー\", \"units\": [{\"goals\": [\"合成データを再現可能な条件で作成できる\", \"特徴量と目的変数を区別できる\", \"データの行数・列数やデータ型を確認できる\", \"目的変数の件数や割合を確認できる\"], \"title\": \"データを作成して全体像をつかむ\", \"minutes\": 35, \"summary\": \"scikit-learnで固定シード付きの合成分類データを作り、pandasで特徴量と目的変数を確認します。実在のデータではなく、機械学習の操作を練習するためのデータであることを確認します。\", \"exercise_count\": 3}, {\"goals\": [\"特徴量と目的変数を分けて扱える\", \"固定シードを指定して再現可能なデータ分割ができる\", \"stratifyを使って分割後のクラス比率を保てる\", \"DummyClassifierの予測結果を基準として確認できる\"], \"title\": \"学習用・評価用データに分けて基準を作る\", \"minutes\": 35, \"summary\": \"train_test_splitでデータを分割し、目的変数の比率を保つ設定を学びます。DummyClassifierを基準モデルとして使い、モデルを評価するときに比較の土台を用意します。\", \"exercise_count\": 3}, {\"goals\": [\"標準化が特徴量の尺度をそろえる処理だと説明できる\", \"Pipelineに前処理とモデルを組み込める\", \"学習用データでfitし、評価用データでpredictできる\", \"学習用データと評価用データに同じ前処理を適用できる\"], \"title\": \"Pipelineで前処理と分類モデルをつなぐ\", \"minutes\": 40, \"summary\": \"StandardScalerとロジスティック回帰をPipelineでつなぎ、学習と予測を実行します。標準化の値を学習用データだけから学習することで、評価用データの情報が前処理に漏れるのを防ぎます。\", \"exercise_count\": 3}, {\"goals\": [\"混同行列から正解・誤分類の内訳を読み取れる\", \"適合率・再現率・F1スコアを計算できる\", \"複数のモデルを同じ条件で評価できる\", \"評価指標の違いを踏まえてモデルの結果を説明できる\"], \"title\": \"分類モデルを評価して比較する\", \"minutes\": 40, \"summary\": \"正解率だけでなく、混同行列・適合率・再現率・F1スコアをコードで算出します。同じデータ分割で複数モデルを比べ、目的に応じて指標を選ぶ考え方を学びます。\", \"exercise_count\": 3}, {\"goals\": [\"交差検証で複数のデータ分割における性能を確認できる\", \"GridSearchCVで調整するパラメータと評価指標を指定できる\", \"学習用データだけでモデルの設定を選べる\", \"未使用の評価用データを使って最終性能を報告できる\"], \"title\": \"交差検証で設定を調整し最終評価する\", \"minutes\": 40, \"summary\": \"Pipelineを保ったままGridSearchCVでモデルの設定を交差検証し、学習用データ内で設定を選びます。選択後は評価用データで一度だけ最終評価し、モデル選択時の情報漏洩を避けます。\", \"exercise_count\": 3}], \"summary\": \"scikit-learnとpandasを使い、データの確認、学習用・評価用データの分割、前処理、モデルの学習、評価、調整までをコードを書きながら学びます。データはscikit-learnで固定シードを指定して生成する合成データを使い、実在の観測データではないことを明示します。\", \"outcomes\": [\"pandasでデータの形や型、目的変数の分布を確認できる\", \"学習用データと評価用データを適切に分割できる\", \"Pipelineを使って前処理とモデル学習を一貫して実行できる\", \"分類モデルを複数の評価指標で評価し、結果を説明できる\", \"交差検証を用いてモデルの設定を調整し、未使用の評価用データで性能を確認できる\"], \"libraries\": [\"pandas\", \"scikit-learn\"], \"quiz_count\": 10}, \"request\": {\"level\": \"basic\", \"title\": \"scikit-learn入門\", \"topic\": \"サンプルデータを用いて、scikit-learnによる機械学習の基本的な操作について学習する。\", \"purpose\": \"pythonのライブラリscikit-learnを使用して、データの前処理から機械学習、評価までの一連の流れについて、実際にコードを記述しながら学習する。\", \"audience\": \"\", \"libraries\": [\"pandas\", \"scikit-learn\"], \"unit_count\": 5, \"course_type\": \"practice\", \"data_summary\": \"\"}}',8,'2026-10-29 02:52:43','2026-10-29 03:03:10');
